// t19_waitgen0 -- generated by gen_t19_waitgen0.py; do not edit by hand.
//
// mb.wait on an already-complete generation must return immediately. The
// sleep and wake predicates have to agree, or the waiter oscillates.
.org 0
start:
    // (1) generation 0 of a barrier nothing has armed. ISA sec 9A.7: every
    //     barrier starts here, so this generation is complete already.
    .li       s1, #0                   // token = {epoch 0, barrier 0}
    mb.wait   s1
    .li       s2, #1
    .assert_eq s2, #1, #1              // reached at all

    // (2) arm and complete generation 1, then wait on it again.
    mb.arm    s3, b0, #1, #0
    mb.arrive b0
    mb.wait   s3
    mb.wait   s3                       // second wait: already complete
    .assert_eq s2, #1, #2

    // (3) a late waiter on an older generation. The '>=' comparison is
    //     there for exactly this, and it is what makes a token that has
    //     been overtaken safe to wait on.
    mb.arm    s4, b0, #1, #0
    mb.arrive b0
    mb.wait   s4
    mb.wait   s3                       // generation 1, long since done
    .assert_eq s2, #1, #3

    // (4) generation 0 of a barrier that has since advanced.
    .li       s5, #0
    mb.wait   s5
    .assert_eq s2, #1, #4

    exit

